
begin;
create table sim_murid_private.grade_counters(teacher_id uuid references public.profiles(id),class_id uuid references public.classes(id),subject_id uuid references public.subjects(id),last_number integer not null,primary key(teacher_id,class_id,subject_id));
create table sim_murid_private.minimum_grades(class_id uuid references public.classes(id),subject_id uuid references public.subjects(id),academic_year_id uuid references public.academic_years(id),semester integer check(semester in(1,2)),value numeric(5,2) not null check(value between 0 and 100),updated_by uuid references public.profiles(id),primary key(class_id,subject_id,academic_year_id,semester));
create table sim_murid_private.assessments(id uuid primary key default gen_random_uuid(),class_id uuid not null references public.classes(id),subject_id uuid not null references public.subjects(id),academic_year_id uuid not null references public.academic_years(id),semester integer not null check(semester in(1,2)),kind text not null check(kind in('PH','ATS','ASAS','Praktik')),ph_number integer,teacher_id uuid not null references public.profiles(id),assessment_date date not null,kkm_snapshot numeric(5,2) not null check(kkm_snapshot between 0 and 100),kkm_fallback boolean not null,voided_at timestamptz,check((kind='PH' and ph_number>0) or(kind<>'PH' and ph_number is null)));
create unique index assessment_nonph on sim_murid_private.assessments(class_id,subject_id,academic_year_id,semester,kind) where kind<>'PH' and voided_at is null;
create table sim_murid_private.assessment_scores(assessment_id uuid references sim_murid_private.assessments(id),student_id uuid references public.profiles(id),value numeric(5,2) check(value between 0 and 100),notes text not null default '' check(length(notes)<=2000),primary key(assessment_id,student_id));
create index scores_student on sim_murid_private.assessment_scores(student_id);
create index assessments_teacher on sim_murid_private.assessments(teacher_id);
create index assessments_class_period on sim_murid_private.assessments(class_id,academic_year_id,semester,subject_id);
create function public.app_teaching_access(p_actor uuid,p_session uuid,p_class uuid,p_subject uuid,p_write boolean default false) returns boolean language sql stable security invoker set search_path='' as $$select public.app_onboarding_ready(p_actor,p_session) and (public.app_education_admin(p_actor,p_session) or(not p_write and public.app_education_task(p_actor,'school_head')) or(public.app_ops_role(p_actor,'teacher') and exists(select 1 from sim_murid_private.lesson_schedules where class_id=p_class and subject_id=p_subject and teacher_id=p_actor and archived_at is null)))$$;
create function public.app_grades_mutate(p_actor uuid,p_session uuid,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare cls uuid;sub uuid;y uuid;sem integer;dt date;target uuid;old sim_murid_private.assessments%rowtype;kkm numeric;fallback boolean;ph integer;item jsonb;begin
 cls=(p_command->>'classId')::uuid;sub=(p_command->>'subjectId')::uuid;target=(p_command->>'id')::uuid;
 if target is not null then select * into old from sim_murid_private.assessments where id=target and voided_at is null;if not found then return jsonb_build_object('code','not_found');end if;cls=old.class_id;sub=old.subject_id;if old.teacher_id<>p_actor and not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;end if;
 if not public.app_teaching_access(p_actor,p_session,cls,sub,true) then return jsonb_build_object('code','denied');end if;
 select academic_year_id into y from public.classes where id=cls and archived_at is null;
 if p_command->>'type'='void' then update sim_murid_private.assessments set voided_at=now() where id=target;return jsonb_build_object('code','saved','id',target);end if;
 dt=(p_command->>'date')::date;sem=case when extract(month from dt)>=7 then 1 else 2 end;
 if not exists(select 1 from public.academic_years where id=y and dt>=make_date(start_year,7,1) and dt<make_date(start_year+1,7,1)) then return jsonb_build_object('code','invalid');end if;
 if p_command->>'type'='kkm' then
 insert into sim_murid_private.minimum_grades values(cls,sub,y,sem,(p_command->>'value')::numeric,p_actor) on conflict(class_id,subject_id,academic_year_id,semester) do update set value=excluded.value,updated_by=p_actor;return jsonb_build_object('code','saved');end if;
 if p_command->>'type'<>'batch' or jsonb_typeof(p_command->'items') is distinct from 'array' or jsonb_array_length(p_command->'items') not between 1 and 500 or p_command->>'kind' not in('PH','ATS','ASAS','Praktik') then return jsonb_build_object('code','invalid');end if;
 if exists(select 1 from jsonb_array_elements(p_command->'items')x group by x->>'studentId' having count(*)>1) then return jsonb_build_object('code','duplicate');end if;
 for item in select value from jsonb_array_elements(p_command->'items') loop if not exists(select 1 from sim_murid_private.enrollments e where e.student_id=(item->>'studentId')::uuid and e.class_id=cls and e.academic_year_id=y) or ((item->>'value')::numeric is not null and (item->>'value')::numeric not between 0 and 100) then return jsonb_build_object('code','invalid');end if;end loop;
 if target is null and p_command->>'kind'<>'PH' then select * into old from sim_murid_private.assessments where class_id=cls and subject_id=sub and academic_year_id=y and semester=sem and kind=p_command->>'kind' and voided_at is null;
 if found then if old.teacher_id<>p_actor and not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;target=old.id;end if;end if;
 if target is not null then
 if old.kind<>p_command->>'kind' or old.academic_year_id<>y or old.semester<>sem then return jsonb_build_object('code','invalid');end if;update sim_murid_private.assessments set assessment_date=dt where id=target;
 else
 select value into kkm from sim_murid_private.minimum_grades where class_id=cls and subject_id=sub and academic_year_id=y and semester=sem;fallback=kkm is null;kkm=coalesce(kkm,75);
 if p_command->>'kind'='PH' then insert into sim_murid_private.grade_counters values(p_actor,cls,sub,1) on conflict(teacher_id,class_id,subject_id) do update set last_number=sim_murid_private.grade_counters.last_number+1 returning last_number into ph;end if;
 insert into sim_murid_private.assessments(class_id,subject_id,academic_year_id,semester,kind,ph_number,teacher_id,assessment_date,kkm_snapshot,kkm_fallback) values(cls,sub,y,sem,p_command->>'kind',ph,p_actor,dt,kkm,fallback) returning id into target;end if;
 insert into sim_murid_private.assessment_scores(assessment_id,student_id,value,notes) select target,(x->>'studentId')::uuid,(x->>'value')::numeric,coalesce(x->>'notes','') from jsonb_array_elements(p_command->'items')x on conflict(assessment_id,student_id) do update set value=excluded.value,notes=excluded.notes;
 return jsonb_build_object('code','saved','id',target);end$$;
do $$declare t text;r record;begin foreach t in array array['grade_counters','minimum_grades','assessments','assessment_scores'] loop execute format('alter table sim_murid_private.%I enable row level security',t);execute format('revoke all on sim_murid_private.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on sim_murid_private.%I to service_role',t);end loop;for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('app_teaching_access','app_grades_mutate') loop execute format('revoke all on function %s from public,anon,authenticated',r.signature);execute format('grant execute on function %s to service_role',r.signature);end loop;end$$;
commit;
